style.css:
@-moz-document domain("roblox.com") {
body {
        background-image: url("https://cdn.openai.com/chat-uploads/file-VVyNvJcDypqtK2bcShhssm/summer%20watercolor%20board.jpg");
        background-size: cover;
        background-repeat: no-repeat;
        background-attachment: fixed;
        background-position: center;
    }

    /* Optional: Makes main content a little transparent for better background view */
    .container-main, .navbar, .content, .footer {
        background-color: rgba(255, 255, 255, 0.8) !important;
    }
}
